util = require('util');
EventEmitter = require('events').EventEmitter;
util.inherits(Device, EventEmitter);

function Device(adapter, connection, gpsServer) {
  /* Inherits EventEmitter class */
  EventEmitter.call(this);

  var _this = this;

  this.connection = connection;
  this.server = gpsServer;
  this.adapter = adapter.adapter(this);

  this.uid = false;
  this.ip = connection.ip;
  this.port = connection.port;
  this.name = false;
  this.loged = false;

  init();
  /* init */
  function init() {

  }

  /****************************************
   RECEIVING DATA FROM THE DEVICE
   ****************************************/
  this.on('data', function (data) {
    var msgParts = _this.adapter.parse_data(data);

   if (this.getUID() === false && (typeof (msgParts.device_id) === 'undefined' || msgParts.device_id === '')) {
    console.log('No device_id in message, but device not logged in yet. Ignoring.');
    return; // Changed from throw to return
  }

  if (msgParts === false) { //something bad happened
    _this.do_log('The message (' + data + ') can\'t be parsed. Discarding...');
    return;
  }

  if (typeof (msgParts.cmd) === 'undefined') {
    console.log('No cmd in message parts, ignoring.');
    return; // Changed from throw to return
  }

  //If the UID of the devices it hasn't been setted, do it now.
  if (this.getUID() === false && msgParts.device_id) {
    this.setUID(msgParts.device_id);
  }

    /************************************
     EXECUTE ACTION
     ************************************/
  _this.make_action(msgParts.action, msgParts);
  });

this.make_action = function (action, msgParts) {
  //If we're not loged
  if (action !== 'login_request' && !_this.loged) {
    _this.adapter.request_login_to_device();
    _this.do_log(_this.getUID() + ' is trying to \'' + action + '\' but it isn\'t loged. Action wasn\'t executed');
    return false;
  }

  switch (action) {
    case 'login_request':
      _this.login_request(msgParts);
      break;
    case 'location':
    case 'ping':  // Add this for backwards compatibility
      _this.ping(msgParts);
      break;
    case 'heartbeat':
      _this.receive_heartbeat(msgParts);
      break;
    case 'alarm':
      _this.receive_alarm(msgParts);
      break;
    case 'status':
      _this.receive_status(msgParts);
      break;
    case 'lbs_location':
      _this.receive_lbs_location(msgParts);
      break;
    default:
      console.log(`Unknown action: ${action}, msgParts:`, JSON.stringify(msgParts));
      _this.do_log('Unknown action: ' + action);
  }
};

  /****************************************
   LOGIN & LOGOUT
   ****************************************/
  this.login_request = function (msgParts) {
    _this.do_log('I\'m requesting to be loged.');
    _this.emit('login_request', this.getUID(), msgParts);
  };

  this.login_authorized = function (val, msgParts) {
    if (val) {
      this.do_log('Device ' + _this.getUID() + ' has been authorized. Welcome!');
      this.loged = true;
      this.adapter.authorize(msgParts);
    } else {
      this.do_log('Device ' + _this.getUID() + ' not authorized. Login request rejected');
    }
  };

  this.logout = function () {
    this.loged = false;
    this.adapter.logout();
  };

  /****************************************
   RECEIVING GPS POSITION FROM THE DEVICE
   ****************************************/
 this.ping = function (msgParts) {
  var gpsData = this.adapter.get_ping_data(msgParts);
  if (gpsData === false) {
    //Something bad happened
    _this.do_log('GPS Data can\'t be parsed. Discarding packet...');
    return false;
  }

  /* Needs:
   latitude, longitude, time
   Optionals:
   orientation, speed, mileage, etc */

  _this.do_log('Position received ( ' + gpsData.latitude + ',' + gpsData.longitude + ' )');
  gpsData.from_cmd = msgParts.cmd;
  gpsData.device_id = _this.getUID();

  this.do_log("Location Requested");
  _this.emit('ping', gpsData, msgParts);  // Emit 'ping' for old system
  _this.emit('location', gpsData, msgParts);  // Emit 'location' for new system

};

  /****************************************
   RECEIVING ALARM
   ****************************************/
  this.receive_alarm = function (msgParts) {
    //We pass the message parts to the adapter and they have to say wich type of alarm it is.
    var alarmData = _this.adapter.receive_alarm(msgParts);
    /* Alarm data must return an object with at least:
     alarm_type: object with this format:
     {'code':'sos_alarm','msg':'SOS Alarm activated by the driver'}
     */
     console.log(this.getUID(), "ALARM RECIEVED");

    _this.emit('alarm', alarmData.code, alarmData, msgParts);
  };

  /****************************************
   SET REFRESH TIME
   ****************************************/
  this.set_refresh_time = function (interval, duration) {
    _this.adapter.set_refresh_time(interval, duration);
  };

  /* adding methods to the adapter */
  this.adapter.get_device = function () {
    return device;
  };

  this.send = function (msg) {
    this.emit('send_data', msg);
    this.connection.write(msg);
    this.do_log('Sending to ' + _this.getUID() + ': ' + msg);
  };

  this.do_log = function (msg) {
    _this.server.do_log(msg, _this.getUID());
  };

  /****************************************
   SOME SETTERS & GETTERS
   ****************************************/
  this.getName = function () {
    return this.name;
  };

  this.setName = function (name) {
    this.name = name;
  };

  this.getUID = function () {
    return this.uid;
  };

  this.setUID = function (uid) {
    this.uid = uid;
  };



  /****************************************
   RECEIVING GPS LOCATION DATA
   ****************************************/
  this.receive_location = function (msgParts) {
    var locationData = this.adapter.get_location_data(msgParts);
    
    if (locationData === false) {
      _this.do_log('Location Data can\'t be parsed. Discarding packet...');
      return false;
    }

    locationData.from_cmd = msgParts.cmd;
    locationData.device_id = _this.getUID();
    locationData.raw_packet = msgParts.raw;

    _this.do_log('Location received ( ' + locationData.latitude + ',' + locationData.longitude + ' )');
    
    _this.emit('location', locationData, msgParts);
  };

  /****************************************
   RECEIVING HEARTBEAT
   ****************************************/
  this.receive_heartbeat = function (msgParts) {
    _this.adapter.receive_heartbeat(msgParts);
    _this.do_log('Heartbeat received from ' + _this.getUID());
    _this.emit('heartbeat', { device_id: _this.getUID(), timestamp: new Date() }, msgParts);
  };

  /****************************************
   RECEIVING ALARM
   ****************************************/
  this.receive_alarm = function (msgParts) {
    var alarmData = _this.adapter.receive_alarm(msgParts);
    
    if (alarmData === false) {
      _this.do_log('Alarm Data can\'t be parsed. Discarding packet...');
      return false;
    }

    alarmData.device_id = _this.getUID();
    alarmData.raw_packet = msgParts.raw;

    console.log(_this.getUID(), "ALARM RECEIVED:", alarmData.alarm_type);
    _this.emit('alarm', alarmData.alarm_type, alarmData, msgParts);
  };

  /****************************************
   RECEIVING STATUS INFORMATION
   ****************************************/
  this.receive_status = function (msgParts) {
    var statusData = _this.adapter.get_status_info(msgParts);
    statusData.device_id = _this.getUID();
    statusData.timestamp = new Date();
    
    _this.do_log('Status received from ' + _this.getUID());
    _this.emit('status', statusData, msgParts);
  };

  /****************************************
   RECEIVING LBS LOCATION
   ****************************************/
  this.receive_lbs_location = function (msgParts) {
    var lbsData = {
      device_id: _this.getUID(),
      timestamp: new Date(),
      raw_data: msgParts.data,
      protocol: msgParts.protocol_id
    };
    
    _this.do_log('LBS Location received from ' + _this.getUID());
    _this.emit('lbs_location', lbsData, msgParts);
  };

  /****************************************
   RECEIVING STRING INFORMATION
   ****************************************/
  this.receive_string_info = function (msgParts) {
    var stringData = {
      device_id: _this.getUID(),
      timestamp: new Date(),
      data: msgParts.string_data,
      protocol: msgParts.protocol_id
    };
    
    _this.do_log('String info received from ' + _this.getUID());
    _this.emit('string_info', stringData, msgParts);
  };

  /****************************************
   RECEIVING GPS MULTI DATA
   ****************************************/
  this.receive_gps_multi = function (msgParts) {
    // Parse multiple GPS points
    var multiData = {
      device_id: _this.getUID(),
      timestamp: new Date(),
      raw_data: msgParts.multi_data,
      protocol: msgParts.protocol_id
    };
    
    _this.do_log('GPS Multi data received from ' + _this.getUID());
    _this.emit('gps_multi', multiData, msgParts);
  };

  /****************************************
   RECEIVING COMMAND RESPONSE
   ****************************************/
  this.receive_command_response = function (msgParts) {
    var responseData = {
      device_id: _this.getUID(),
      timestamp: new Date(),
      response: msgParts.response,
      protocol: msgParts.protocol_id
    };
    
    _this.do_log('Command response received from ' + _this.getUID());
    _this.emit('command_response', responseData, msgParts);
  };

  // ... existing code ...

  /****************************************
   SEND COMMAND TO DEVICE
   ****************************************/
  this.sendCommand = function (command, params) {
    _this.adapter.sendCommand(command, params);
  };


}

module.exports =  Device;
